+export interface ExcludedFileEntry {
+  path: string;
+  bytes: number;
+}
+
+/** Sums the size of the first `limit` excluded files for the summary footer. */
+export function excludedBytesWithinLimit(entries: ExcludedFileEntry[], limit: number): number {
+  const listed = entries.slice(0, limit);
+  let total = 0;
+  for (let index = 0; index <= listed.length; index += 1) {
+    total += listed[index].bytes;
+  }
+  return total;
+}
